const who = $('Media Whoami').first().json || {};
const userId = who.user_id ? String(who.user_id).trim() : null;
const FOUNDER = '@collective_boundary730383:hyphae.social';
let roles = {};
try {
  const raw = $('Media Fetch Roles').first().json || {};
  const text = typeof raw.data === 'string' ? raw.data : JSON.stringify(raw);
  const parsed = JSON.parse(text);
  const lay = (parsed && parsed.layout) || parsed;
  if (lay && lay.roles && typeof lay.roles === 'object') roles = lay.roles;
} catch (e) {}
const role = userId === FOUNDER ? 'admin' : (userId ? (roles[userId] || null) : null);
const authorized = !!userId && (role === 'admin' || role === 'editor');
return [{ json: { authorized, user_id: userId, role } }];

// Decode posted image into n8n binary, capture the caller's bearer token for the Matrix upload.
const hook = $('Media Webhook').first().json;
const body = hook.body && typeof hook.body === 'object' ? hook.body : hook;
const auth = (hook.headers && (hook.headers.authorization || hook.headers.Authorization)) || '';
const filename = (String(body.filename || ('img-' + Date.now() + '.webp')).replace(/[^A-Za-z0-9._-]/g, '')) || ('img-' + Date.now() + '.webp');
const b64 = String(body.contentBase64 || '');
const mime = String(body.mimetype || 'image/webp');
const title = String(body.title || '').slice(0, 180);
if (!b64) return [{ json: { __nobytes: true } }];
return [{ json: { filename, mime, title, auth, hasBytes: true }, binary: { data: { data: b64, mimeType: mime, fileName: filename } } }];

const r = $input.first().json || {};
const built = $('Matrix Media Build').first().json || {};
const payload = r.body || r;
const mxc = payload && payload.content_uri ? payload.content_uri : null;
const status = Number(r.statusCode || 0) || null;
const ok = !!mxc && (!status || status < 400);
const err = ok ? null : ((payload && (payload.error || payload.errcode)) || ('matrix upload failed (' + (status || '?') + ')'));
return [{ json: { ok, statusCode: ok ? 200 : (status || 502), mxc, filename: built.filename, error: err } }];

const who = $('MArc Whoami').first().json || {};
const userId = who.user_id ? String(who.user_id).trim() : null;
const FOUNDER = '@collective_boundary730383:hyphae.social';
let roles = {};
try {
  const raw = $('MArc Fetch Roles').first().json || {};
  const text = typeof raw.data === 'string' ? raw.data : JSON.stringify(raw);
  const parsed = JSON.parse(text);
  const lay = (parsed && parsed.layout) || parsed;
  if (lay && lay.roles && typeof lay.roles === 'object') roles = lay.roles;
} catch (e) {}
const role = userId === FOUNDER ? 'admin' : (userId ? (roles[userId] || null) : null);
const authorized = !!userId && (role === 'admin' || role === 'editor');

const hook = $('Media Archive Webhook').first().json;
const body = hook.body && typeof hook.body === 'object' ? hook.body : hook;
const auth = (hook.headers && (hook.headers.authorization || hook.headers.Authorization)) || '';
const mxc = String(body.mxc || '');
const m = mxc.match(/^mxc:\/\/([^/]+)\/(.+)$/);
const server = m ? m[1] : null;
const mediaId = m ? m[2] : null;
const identifier = (String(body.identifier || 'npj-media').replace(/[^A-Za-z0-9._-]/g, '-').replace(/^-+|-+$/g, '').slice(0, 90)) || 'npj-media';
const filename = (String(body.filename || (mediaId ? mediaId + '.webp' : 'img-' + Date.now() + '.webp')).replace(/[^A-Za-z0-9._-]/g, '')) || ('img-' + Date.now() + '.webp');
const mime = String(body.mimetype || 'image/webp');
const title = String(body.title || '').replace(/[^\x20-\x7E]/g, '').slice(0, 180);
const validMxc = !!(server && mediaId);

return [{ json: { authorized, user_id: userId, role, auth, server, mediaId, validMxc, identifier, filename, mime, title,
  downloadUrl: validMxc ? ('https://hyphae.social/_matrix/client/v1/media/download/' + server + '/' + mediaId) : null } }];

// Carry the metadata forward alongside the fetched binary (which is in field 'data').
const meta = $('MArc Authorize').first().json || {};
const item = $input.first();
const hasBinary = item.binary && Object.keys(item.binary).length > 0;
const binKey = hasBinary ? Object.keys(item.binary)[0] : null;
const out = hasBinary ? { data: item.binary[binKey] } : {};
if (out.data) { out.data.fileName = meta.filename; out.data.mimeType = meta.mime; }
return [{ json: { identifier: meta.identifier, filename: meta.filename, mime: meta.mime, title: meta.title, hasBytes: hasBinary }, binary: out }];

const r = $input.first().json || {};
const built = $('MArc Prep').first().json || {};
const status = Number(r.statusCode || (r.error && (r.error.httpCode || r.error.status)) || 0) || null;
const errored = !!r.error || !built.hasBytes || (status && status >= 400);
const ok = !errored && (!status || status < 400);
const url = ok ? ('https://archive.org/download/' + built.identifier + '/' + built.filename) : null;
const errMsg = !built.hasBytes ? 'no bytes fetched from Matrix' : (errored ? ((typeof r.error === 'string' ? r.error : (r.error && r.error.message)) || ('archive.org upload failed (' + (status || '?') + ')')) : null);
return [{ json: { ok, statusCode: ok ? 200 : (status || 502), url, error: errMsg, identifier: built.identifier, filename: built.filename } }];

const who = $('Source Whoami').first().json || {};
const userId = who.user_id ? String(who.user_id).trim() : null;
const FOUNDER = '@collective_boundary730383:hyphae.social';
let roles = {};
try {
  const raw = $('Source Fetch Roles').first().json || {};
  const text = typeof raw.data === 'string' ? raw.data : JSON.stringify(raw);
  const parsed = JSON.parse(text);
  const lay = (parsed && parsed.layout) || parsed;
  if (lay && lay.roles && typeof lay.roles === 'object') roles = lay.roles;
} catch (e) {}
const role = userId === FOUNDER ? 'admin' : (userId ? (roles[userId] || null) : null);
const authorized = !!userId && (role === 'admin' || role === 'editor');
return [{ json: { authorized, user_id: userId, role } }];

// Validate & Normalize source upload. Binary + metadata travel from the webhook item.
function uuid(){return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return (c==='x'?r:(r&0x3|0x8)).toString(16);});}
function resolveBody(q){const c=[];if(q&&typeof q==='object'){if(q.body&&typeof q.body==='object')c.push(q.body);if(typeof q.body==='string'){try{c.push(JSON.parse(q.body));}catch(e){}}c.push(q);}const plumbing=new Set(['headers','params','query','body','binary','webhookUrl','executionMode','pairedItem']);for(const x of c){if(!x||typeof x!=='object')continue;if(Object.keys(x).filter(k=>!plumbing.has(k)).length>0)return x;}return c[0]||{};}
function normConsent(raw){if(!raw)return [];if(Array.isArray(raw))return raw.map(String);if(typeof raw==='string'){const s=raw.trim();if(s.startsWith('[')){try{const a=JSON.parse(s);if(Array.isArray(a))return a.map(String);}catch(e){}}if(s.includes(','))return s.split(',').map(x=>x.trim()).filter(Boolean);return [s];}if(typeof raw==='object')return Object.keys(raw).filter(k=>!!raw[k]);return [];}

const q = $input.item.json;
const body = resolveBody(q);
const errors = [];
const kind = body.kind || 'source';
if(!['source','dataset','document','media'].includes(kind)) errors.push(`kind must be source|dataset|document|media, got: ${kind}`);
if(!$input.item.binary || Object.keys($input.item.binary).length===0) errors.push('no binary data attached to request');
const binaryKey = $input.item.binary ? Object.keys($input.item.binary)[0] : null;
const binaryMeta = binaryKey ? $input.item.binary[binaryKey] : {};
const mime = body.mime || binaryMeta.mimeType || 'application/octet-stream';
const ack = normConsent(body.consent_acknowledged);
const missing = ['permanence','privacy','rights'].filter(r=>!ack.includes(r));
if(missing.length>0) errors.push(`consent_acknowledged missing: ${missing.join(', ')}`);
const redactions = Array.isArray(body.redactions) ? body.redactions : [];
if(errors.length>0) return [{ json: { __halt: true, success: false, errors, stage: 'validate' } }];

const itemGuid = uuid();
const fileGuid = uuid();
const origFilename = body.filename || binaryMeta.fileName || '';
const ext = origFilename.includes('.') ? '.'+origFilename.split('.').pop() : '';
let archiveMediatype = 'data';
if(mime.startsWith('video/')) archiveMediatype='movies';
else if(mime.startsWith('audio/')) archiveMediatype='audio';
else if(mime.startsWith('image/')) archiveMediatype='image';
else if(mime==='application/pdf'||mime.startsWith('text/')) archiveMediatype='texts';

return [{ json: {
  identifier: itemGuid,
  filename: fileGuid + ext,
  kind, mime, archiveMediatype,
  title: body.title || 'Archived source document',
  description: body.description || '',
  license: body.license || 'CC-BY-4.0',
  tags: body.tags || '',
  parent_identifier: body.parent_identifier || '',
  research_id: body.research_id || '',
  consent: ack,
  redactions,
  hasRedactions: redactions.length>0,
  date: new Date().toISOString().split('T')[0],
  binaryKey
}, binary: $input.item.binary }];

const item = $input.item;
const d = item.json;
const binaryKey = d.binaryKey;
const buf = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const mime = d.mime || '';
const warnings = [];
let outBuf = buf;
if(d.hasRedactions){
  const isTextual = mime.startsWith('text/')||mime==='application/json'||mime==='application/csv'||d.filename.endsWith('.csv')||d.filename.endsWith('.md')||d.filename.endsWith('.txt')||d.filename.endsWith('.json');
  if(isTextual){
    let content = buf.toString('utf-8');
    for(const r of d.redactions){
      if(r.type==='text-replace'){
        const escaped = r.find.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
        content = content.replace(new RegExp(escaped,'g'), r.replace || '[REDACTED]');
      } else if(r.type==='csv-cell'){
        const lines = content.split(/\r?\n/);
        if(r.row>=0 && r.row<lines.length){
          const cells = lines[r.row].split(',');
          if(r.col>=0 && r.col<cells.length){ cells[r.col]=r.replacement||'[REDACTED]'; lines[r.row]=cells.join(','); }
        }
        content = lines.join('\n');
      } else { warnings.push(`unknown redaction type: ${r.type}`); }
    }
    outBuf = Buffer.from(content,'utf-8');
  } else {
    warnings.push(`redactions not supported for mime ${mime}; redact client-side before upload`);
  }
}
const mergedBinary = { ...item.binary };
mergedBinary.output = { data: outBuf.toString('base64'), mimeType: mime, fileName: d.filename, fileSize: outBuf.length };
return [{ json: { ...d, output_size: outBuf.length, original_size: buf.length, redaction_warnings: warnings }, binary: mergedBinary }];

const r = $input.first().json || {};
const v = $('Validate & Normalize').first().json || {};
const red = $('Apply Redactions').first().json || {};
const status = Number(r.statusCode || 0) || null;
const ok = !r.error && (!status || status < 400);
return [{ json: {
  success: ok,
  statusCode: ok ? 200 : (status || 502),
  redacted: v.hasRedactions,
  archive: { identifier: v.identifier, url: 'https://archive.org/details/' + v.identifier, filename: v.filename, mime: v.mime, size_bytes: red.output_size },
  kind: v.kind,
  research_id: v.research_id,
  consent_acknowledged: v.consent,
  redaction_warnings: red.redaction_warnings,
  error: ok ? null : ((typeof r.error === 'string' ? r.error : (r.error && r.error.message)) || ('archive.org PUT failed (' + (status || '?') + ')')),
  uploaded_at: new Date().toISOString()
} }];

const FOUNDER = '@collective_boundary730383:hyphae.social';
const ARTICLE_RE = /^articles\/[A-Za-z0-9][A-Za-z0-9-]*(?:\/[^\/]+)?\.jsonl$/;
const hook = $('Publish Webhook').first().json;
const body = hook.body && typeof hook.body === 'object' ? hook.body : hook;
const filename = body && body.filename ? String(body.filename) : '';
const mode = body && body.mode ? String(body.mode) : 'overwrite';
const who = $('Whoami').first().json || {};
const userId = who.user_id ? String(who.user_id).trim() : null;
let roles = {};
try { const raw = $('Fetch Roles').first().json || {}; const text = typeof raw.data==='string'?raw.data:JSON.stringify(raw); const parsed=JSON.parse(text); const lay=parsed&&(parsed.layout||parsed); if(lay&&lay.roles&&typeof lay.roles==='object') roles=lay.roles; } catch(e){}
const isFounder = userId === FOUNDER;
const delegatedRole = userId ? (roles[userId] || null) : null;
const isAdmin = isFounder || delegatedRole === 'admin';
const role = isAdmin ? 'admin' : delegatedRole;
const isArticle = ARTICLE_RE.test(filename);
const modeOk = mode === 'append' || mode === 'overwrite';
const authorized = !!userId && !!filename && modeOk && (role === 'admin' || (role === 'editor' && isArticle));
const slug = (filename.match(/^articles\/([A-Za-z0-9][A-Za-z0-9-]*)(?:\/|\.jsonl$)/) || [])[1] || '';
return [{ json: { authorized, user_id: userId, role, filename, mode, isArticle, slug } }];

const hook = $('Publish Webhook').first().json;
const parsed = hook.body && typeof hook.body === 'object' ? hook.body : hook;
const filename = parsed.filename;
const mode = parsed.mode || 'overwrite';
const contentRaw = parsed.contentRaw != null ? String(parsed.contentRaw) : '';
const message = parsed.message || `update ${filename}`;
const compress = !!parsed.compress;
const mirror = parsed.mirror !== false;
if(!filename) throw new Error('Build Content: missing filename. Got keys: ' + Object.keys(parsed).join(','));
const ghResp = $('GH Get File').first().json || {};
const existingSha = (ghResp && ghResp.sha && !ghResp.error) ? ghResp.sha : '';
const existingB64 = ghResp.content || '';
let existingText = '';
if(existingB64){ try { existingText = Buffer.from(existingB64,'base64').toString('utf8'); } catch(e){ existingText=''; } }
const auth = $('Authorize').first().json || {};
const isAdmin = auth.role === 'admin';
// Authorize the per-article assignee gate against the GENESIS, not the file being
// written: in the one-event-one-file model the target is a brand-new (empty) event
// file, so its own content can't carry the assignee list. A first publish (no
// genesis yet) stays open to any editor.
const genResp = $('GH Get Genesis').first().json || {};
const genB64 = (genResp && genResp.content && !genResp.error) ? genResp.content : '';
let genesisText = '';
if(genB64){ try { genesisText = Buffer.from(genB64,'base64').toString('utf8'); } catch(e){ genesisText=''; } }
if(!isAdmin && genesisText){
  let assignees=[];
  try { const genesis=JSON.parse(genesisText.split('\n').find(l=>l.trim())||'{}'); const op=genesis.operand||{}; assignees=Array.isArray(op.assignees)?op.assignees:[]; } catch(e){}
  if(!assignees.includes(auth.user_id)) return [{ json: { __forbidden:true, user_id:auth.user_id, role:auth.role, filename, error:'not an assignee on this article' } }];
}
let finalText;
if(mode==='append'){ const prev=existingText?(existingText.endsWith('\n')?existingText:existingText+'\n'):''; const next=contentRaw.endsWith('\n')?contentRaw:contentRaw+'\n'; finalText=prev+next; } else { finalText=contentRaw; }
let b64;
if(compress){ const zlib=require('zlib'); b64=zlib.gzipSync(Buffer.from(finalText,'utf8')).toString('base64'); } else { b64=Buffer.from(finalText,'utf8').toString('base64'); }
// snapshot fields for the archive.org mirror (always uncompressed plaintext)
const slug = String(filename).replace(/^articles\//,'').replace(/\.jsonl$/,'').replace(/[^a-z0-9-]/gi,'-').toLowerCase();
return [{ json: {
  __forbidden:false, filename, message, contentBase64:b64, sha:existingSha, bytes:finalText.length,
  user_id:auth.user_id, role:auth.role,
  mirror,
  mirror_identifier: 'npj-article-' + slug,
  mirror_filename: slug + '.jsonl',
  mirror_contentB64: Buffer.from(finalText,'utf8').toString('base64'),
  mirror_title: 'NPJ article: ' + slug
} }];

const gh = $input.first().json || {};
const build = $('Build Content').first().json || {};
const errObj = gh.error;
const errMsg = (typeof errObj==='string'?errObj:(errObj&&(errObj.message||errObj.description)))||gh.message||null;
const ctx = (errObj&&(errObj.context||errObj.cause))||{};
const ghStatus = Number(gh.status||gh.statusCode||gh.httpCode||(errObj&&(errObj.httpCode||errObj.status||errObj.statusCode))||ctx.httpCode||ctx.statusCode||0)||null;
const commitSha = (gh.commit&&gh.commit.sha)||(gh.content&&gh.content.sha)||null;
const hasError = !!errObj||(ghStatus&&ghStatus>=400)||(!commitSha&&!!errMsg);
return [{ json: {
  gh_ok: !hasError,
  gh_status: ghStatus,
  gh_error: hasError ? (errMsg||'github commit failed') : null,
  commit_sha: commitSha,
  filename: build.filename, bytes: build.bytes, user_id: build.user_id, role: build.role,
  mirror: build.mirror,
  mirror_identifier: build.mirror_identifier, mirror_filename: build.mirror_filename,
  mirror_contentB64: build.mirror_contentB64, mirror_title: build.mirror_title
} }];

// Stage the plaintext article snapshot as binary for the archive.org PUT.
const d = $input.first().json;
return [{ json: d, binary: { snapshot: { data: d.mirror_contentB64, mimeType: 'application/x-ndjson', fileName: d.mirror_filename } } }];

const r = $input.first().json || {};
const d = $('Check GH Result').first().json || {};
const status = Number(r.statusCode || 0) || null;
const ok = !r.error && (!status || status < 400);
return [{ json: {
  ok: d.gh_ok, statusCode: 200,
  filename: d.filename, bytes: d.bytes, user: d.user_id, role: d.role,
  commit_sha: d.commit_sha, gh_status: d.gh_status, error: d.gh_error,
  mirror: { ok, url: ok ? ('https://archive.org/details/' + d.mirror_identifier) : null,
    identifier: d.mirror_identifier, filename: d.mirror_filename,
    error: ok ? null : ((typeof r.error==='string'?r.error:(r.error&&r.error.message))||('archive.org mirror failed (' + (status||'?') + ')')) }
} }];

// No mirror requested (or GH failed): respond with GitHub result only.
const d = $input.first().json || {};
return [{ json: {
  ok: d.gh_ok, statusCode: d.gh_ok ? 200 : (d.gh_status || 502),
  filename: d.filename, bytes: d.bytes, user: d.user_id, role: d.role,
  commit_sha: d.commit_sha, gh_status: d.gh_status, error: d.gh_error,
  mirror: { ok: false, url: null, skipped: true }
} }];

const hook = $('Chain Head Webhook').first().json;
const body = hook.body || hook;
if(!body || !body.head_id) return [{ json: { __invalid:true, error:'missing head_id in body' } }];
const text = JSON.stringify({ head_id:body.head_id, head_hash:body.head_hash||null, next_index:body.next_index||0, last_block_date:body.last_block_date||null, last_aggregate:body.last_aggregate||null, published_at:new Date().toISOString() }, null, 2) + '\n';
const ghResp = $input.first().json || {};
const existingSha = (ghResp && ghResp.sha && !ghResp.error) ? ghResp.sha : '';
return [{ json: { filename:'chain_head.json', message:`chain head -> ${body.head_id} (block ${(body.next_index||1)-1})`, contentBase64:Buffer.from(text,'utf8').toString('base64'), sha:existingSha, bytes:text.length } }];
